function actionBar_getStateDisable($buttonName)
{
    if (isset($this->sc_actionbar_disabled[$buttonName]) && $this->sc_actionbar_disabled[$buttonName]) {
        return ' disabled';
    }

    return '';
}

function actionBar_getStateHide($buttonName)
{
    if (isset($this->sc_actionbar_hidden[$buttonName]) && $this->sc_actionbar_hidden[$buttonName]) {
        return ' sc-actionbar-button-hidden';
    }

    return '';
}

function actionBar_nestedGridSubmenu($menuDivId, $menuVarName, $multiRecord, $checkRow, $nestedGridButtonList)
{
    $menuHtml  = "<script>var $menuVarName;</script>";
    $menuHtml .= "<div id=\"$menuDivId\" style=\"display: none; margin: 0px;padding: 0px;position: absolute;box-shadow: rgba(34, 36, 38, 0.15) 0px 2px 3px 0px;border: 1px solid rgba(34, 36, 38, 0.15);border-radius: 0.285714rem;transition: opacity 0.1s;z-index:9;\" onMouseEnter=\"showNestedGridLinks('$menuDivId', $menuVarName)\" onMouseLeave=\"$menuVarName = hideNestedGridLinks('$menuDivId', 'a')\">";
    $menuHtml .= "<table class='SC_SubMenuApp' border='0' cellpadding='0' cellspacing='0'>";
    foreach ($nestedGridButtonList as $nestedGridInfo) {
        $menuHtml .= "<tr class=\"scGridFieldOver\" style=\"cursor:pointer\" data-actionbar-row=\"{$multiRecord}\" data-actionbar-checkrow=\"{$checkRow}\" onclick=\"scActionbarJavascript_{$nestedGridInfo['name']}($(this).attr('data-actionbar-row'), thisNestedGridCheckRow)\" >";
        $menuHtml .= "<td nowrap class='scBtnGrpBackground scGridFieldOver' onMouseover=\"this.style.setProperty('background',getComputedStyle(document.querySelector('.scGridFieldOver')).backgroundColor,'important');\" onMouseout=\"this.style.setProperty('background', '', '')\" style=\"padding:10px;border-bottom:none;display:flex;justify-content:space-between;align-items:center;\">";
        $menuHtml .= "<span>" . $nestedGridInfo['label'] . "</span>";
        $menuHtml .= "<span id='sc-subcons-caret-{$nestedGridInfo['name']}{$multiRecord}' class='sc-subcons-caret' style='padding-left: 10px'><i class='fas fa-caret-down'></i></span>";
        $menuHtml .= "</td>";
        $menuHtml .= "</tr>";
    }
    $menuHtml .= "</table>";
    $menuHtml .= "</div>";

    return $menuHtml;
}

