    function scGetColumnOrderRule($fieldName)
    {
        $sortRule = 'nosort';
        if ($_SESSION['sc_session'][$this->Ini->sc_page]['grid_participantes_rsvp_1']['ordem_cmp'] == $fieldName) {
            if ($_SESSION['sc_session'][$this->Ini->sc_page]['grid_participantes_rsvp_1']['ordem_label'] == 'desc') {
                $sortRule = 'desc';
            } else {
                $sortRule = 'asc';
            }
        }
        return $sortRule;
    }

    function scGetColumnOrderIcon($fieldName, $sortRule, $skipUnusedClass = false)
    {
        $unusedClass = $skipUnusedClass ? '' : ' sc-grid-order-icon-unused';        if ('desc' == $sortRule) {
            return "<img src=\"" . $this->Ini->path_img_global . "/" . $this->Ini->Label_sort_desc . "\" />";
        } elseif ('asc' == $sortRule) {
            return "<img src=\"" . $this->Ini->path_img_global . "/" . $this->Ini->Label_sort_asc . "\" />";
        } elseif ('' != $this->Ini->Label_sort) {
            return "<img src=\"" . $this->Ini->path_img_global . "/" . $this->Ini->Label_sort . "\" />";
        } else {
            return '';
        }
    }

    function scIsFieldNumeric($fieldName)
    {
        switch ($fieldName) {
            case "participante_id":
                return true;
            case "part_id_evento":
                return true;
            case "part_id_evento_publico":
                return true;
            case "part_id_evento_regional":
                return true;
            case "part_cod_usuario":
                return true;
            case "part_bloqueio_id":
                return true;
        }
        return false;
    }

    function scGetDefaultFieldOrder($fieldName)
    {
        switch ($fieldName) {
            case "participante_id":
                return 'desc';
            case "part_id_evento":
                return 'desc';
            case "part_id_evento_publico":
                return 'desc';
            case "part_id_evento_regional":
                return 'desc';
            case "part_dt_nasc":
                return 'desc';
            case "part_validade_pass":
                return 'desc';
            case "part_cod_usuario":
                return 'desc';
            case "part_dt_cadastro":
                return 'desc';
            case "part_dt_alteracao":
                return 'desc';
            case "part_dt_alt_contato_rsvp":
                return 'desc';
            case "part_dt_alt_presenca":
                return 'desc';
            case "part_dt_solicit_especial":
                return 'desc';
            case "part_dt_programacao":
                return 'desc';
            case "part_dt_aereo":
                return 'desc';
            case "par_dt_hospedagem":
                return 'desc';
            case "part_dt_transfer":
                return 'desc';
            case "part_dt_opcionais":
                return 'desc';
            case "part_save_the_date":
                return 'desc';
            case "part_bloqueio_id":
                return 'desc';
        }
        return 'asc';
    }

