   if ($_SESSION['sc_session'][$this->Ini->sc_page]['grid_participantes_rsvp_1']['embutida'] || $_SESSION['sc_session'][$this->Ini->sc_page]['grid_participantes_rsvp_1']['opcao'] == "pdf" || $_SESSION['sc_session'][$this->Ini->sc_page]['grid_participantes_rsvp_1']['embutida_pdf'] == "pdf")
   {
       $this->NM_colspan--;
   } 
   foreach ($this->NM_cmp_hidden as $Cmp => $Hidden)
   {
       if ($Hidden == "off" && !isset($this->All_nested_line[$Cmp]))
       {
           $this->NM_colspan--;
       }
   }
   if ($_SESSION['sc_session'][$this->Ini->sc_page]['grid_participantes_rsvp_1']['embutida_grid'])
