    function getFieldHighlight($filter_type, $field, $str_value, $str_value_original='')
    {
        $str_html_ini = '<div class="highlight">';
        $str_html_fim = '</div>';

        if($filter_type == 'advanced_search')
        {
            if (
                isset($_SESSION['sc_session'][$this->Ini->sc_page]['grid_participantes_rsvp_1']['campos_busca'][ $field ]) &&
                isset($_SESSION['sc_session'][$this->Ini->sc_page]['grid_participantes_rsvp_1']['campos_busca'][ $field . "_cond" ]) &&
                !empty($_SESSION['sc_session'][$this->Ini->sc_page]['grid_participantes_rsvp_1']['campos_busca'][ $field ]) &&
                (
                    $_SESSION['sc_session'][$this->Ini->sc_page]['grid_participantes_rsvp_1']['campos_busca'][ $field . "_cond"] == 'qp' ||
                    $_SESSION['sc_session'][$this->Ini->sc_page]['grid_participantes_rsvp_1']['campos_busca'][ $field . "_cond"] == 'eq' ||
                    $_SESSION['sc_session'][$this->Ini->sc_page]['grid_participantes_rsvp_1']['campos_busca'][ $field . "_cond"] == 'ii' ||
                    $_SESSION['sc_session'][$this->Ini->sc_page]['grid_participantes_rsvp_1']['campos_busca'][ $field . "_cond"] == 'aw'
                )
            )
            {
                if($_SESSION['sc_session'][$this->Ini->sc_page]['grid_participantes_rsvp_1']['campos_busca'][ $field . "_cond"] == 'qp')
                {
                    if(is_array($_SESSION['sc_session'][$this->Ini->sc_page]['grid_participantes_rsvp_1']['campos_busca'][ $field ]))
                    {
                        foreach ($_SESSION['sc_session'][$this->Ini->sc_page]['grid_participantes_rsvp_1']['campos_busca'][ $field ] as $ind => $vals)
                        {
                            if(strcasecmp($vals, $str_value) == 0)
                            {
                                $str_value = $str_html_ini. $str_value .$str_html_fim;
                            }
                            elseif(strcasecmp($vals, $str_value_original) == 0)
                            {
                                $str_value = $str_html_ini. $str_value .$str_html_fim;
                            }
                            else
                            {
                                $keywords = preg_quote($vals, '/');
                                $str_value = preg_replace('/'. $keywords .'/i', $str_html_ini . '$0' . $str_html_fim, $str_value);
                            }
                        }
                    }
                    else
                    {
                        if(strcasecmp($_SESSION['sc_session'][$this->Ini->sc_page]['grid_participantes_rsvp_1']['campos_busca'][ $field ], $str_value) == 0)
                        {
                            $str_value = $str_html_ini. $str_value .$str_html_fim;
                        }
                        elseif(strcasecmp($_SESSION['sc_session'][$this->Ini->sc_page]['grid_participantes_rsvp_1']['campos_busca'][ $field ], $str_value_original) == 0)
                        {
                            $str_value = $str_html_ini. $str_value .$str_html_fim;
                        }
                        else
                        {
                            $keywords = preg_quote($_SESSION['sc_session'][$this->Ini->sc_page]['grid_participantes_rsvp_1']['campos_busca'][ $field ], '/');
                            $str_value = preg_replace('/'. $keywords .'/i', $str_html_ini . '$0' . $str_html_fim, $str_value);
                        }
                    }
                }
                elseif($_SESSION['sc_session'][$this->Ini->sc_page]['grid_participantes_rsvp_1']['campos_busca'][ $field . "_cond"] == 'aw')
                {
                    $args  = explode(" ", $_SESSION['sc_session'][$this->Ini->sc_page]['grid_participantes_rsvp_1']['campos_busca'][ $field ]);
                    foreach ($args as $cada_args) {
                        if (empty($cada_args)) {
                            continue;
                        }
                        if(strcasecmp($cada_args, $str_value) == 0)
                        {
                            $str_value = $str_html_ini. $str_value .$str_html_fim;
                        }
                        elseif(!empty($str_value_original) && $str_value_original != '&nbsp;' && strcasecmp($cada_args, $str_value_original) == 0)
                        {
                            $str_value = $str_html_ini. $str_value .$str_html_fim;
                        }
                        else
                        {
                            $keywords = preg_quote($cada_args, '/');
                            $str_value = preg_replace('/'. $keywords .'/i', $str_html_ini . '$0' . $str_html_fim, $str_value);
                        }
                    }
                }
                elseif($_SESSION['sc_session'][$this->Ini->sc_page]['grid_participantes_rsvp_1']['campos_busca'][ $field . "_cond"] == 'eq')
                {
                    if(is_array($_SESSION['sc_session'][$this->Ini->sc_page]['grid_participantes_rsvp_1']['campos_busca'][ $field ]))
                    {
                        foreach ($_SESSION['sc_session'][$this->Ini->sc_page]['grid_participantes_rsvp_1']['campos_busca'][ $field ] as $ind => $vals)
                        {
                            if(strcasecmp($vals, $str_value) == 0)
                            {
                                $str_value = $str_html_ini. $str_value .$str_html_fim;
                            }
                            elseif(strcasecmp($vals, $str_value_original) == 0)
                            {
                                $str_value = $str_html_ini. $str_value .$str_html_fim;
                            }
                        }
                    }
                    else
                    {
                        if(strcasecmp($_SESSION['sc_session'][$this->Ini->sc_page]['grid_participantes_rsvp_1']['campos_busca'][ $field ], $str_value) == 0)
                        {
                            $str_value = $str_html_ini. $str_value .$str_html_fim;
                        }
                        elseif(strcasecmp($_SESSION['sc_session'][$this->Ini->sc_page]['grid_participantes_rsvp_1']['campos_busca'][ $field ], $str_value_original) == 0)
                        {
                            $str_value = $str_html_ini. $str_value .$str_html_fim;
                        }
                    }
                }
                elseif($_SESSION['sc_session'][$this->Ini->sc_page]['grid_participantes_rsvp_1']['campos_busca'][ $field . "_cond"] == 'ii')
                {
                    if(is_array($_SESSION['sc_session'][$this->Ini->sc_page]['grid_participantes_rsvp_1']['campos_busca'][ $field ]))
                    {
                        foreach ($_SESSION['sc_session'][$this->Ini->sc_page]['grid_participantes_rsvp_1']['campos_busca'][ $field ] as $ind => $vals)
                        {
                            if(strcasecmp($vals, substr($str_value, 0, strlen($vals))) == 0)
                            {
                                $str_value = $str_html_ini. substr($str_value, 0, strlen($vals)) .$str_html_fim . substr($str_value, strlen($vals));
                            }
                        }
                    }
                    else
                    {
                        if(strcasecmp($_SESSION['sc_session'][$this->Ini->sc_page]['grid_participantes_rsvp_1']['campos_busca'][ $field ], substr($str_value, 0, strlen($_SESSION['sc_session'][$this->Ini->sc_page]['grid_participantes_rsvp_1']['campos_busca'][ $field ]))) == 0)
                        {
                            $str_value = $str_html_ini. substr($str_value, 0, strlen($_SESSION['sc_session'][$this->Ini->sc_page]['grid_participantes_rsvp_1']['campos_busca'][ $field ])) .$str_html_fim . substr($str_value, strlen($_SESSION['sc_session'][$this->Ini->sc_page]['grid_participantes_rsvp_1']['campos_busca'][ $field ]));
                        }
                    }
                }
            }
        }
        elseif($filter_type == 'filterbuilder')
        {
            if (
                isset($_SESSION['sc_session'][$this->Ini->sc_page]['grid_participantes_rsvp_1']['dyn_search']) &&
                !empty($_SESSION['sc_session'][$this->Ini->sc_page]['grid_participantes_rsvp_1']['dyn_search'])
            )
            {
                foreach($_SESSION['sc_session'][$this->Ini->sc_page]['grid_participantes_rsvp_1']['dyn_search'] as $_fld)
                {
                    if($_fld['cmp'] == $field)
                    {
                        $vals = (isset($_fld['val_formated'])?$_fld['val_formated']:"");

                        if($_fld['opc'] == 'qp')
                        {
                           if(strcasecmp($vals, $str_value) == 0)
                           {
                              $str_value = $str_html_ini. $str_value .$str_html_fim;
                           }
                           elseif(strcasecmp($vals, $str_value_original) == 0)
                           {
                              $str_value = $str_html_ini. $str_value .$str_html_fim;
                           }
                           else
                           {
                              $keywords = preg_quote($vals, '/');
                              $str_value = preg_replace('/'. $keywords .'/i', $str_html_ini . '$0' . $str_html_fim, $str_value);
                           }
                        }
                        elseif($_fld['opc'] == 'eq')
                        {
                            if(strcasecmp($vals, $str_value) == 0)
                            {
                               $str_value = $str_html_ini. $str_value .$str_html_fim;
                            }
                            elseif(strcasecmp($vals, $str_value_original) == 0)
                            {
                               $str_value = $str_html_ini. $str_value .$str_html_fim;
                            }
                        }
                        elseif($_fld['opc'] == 'ii')
                        {
                            if(strcasecmp($vals, substr($str_value, 0, strlen($vals))) == 0)
                            {
                                $str_value = $str_html_ini. substr($str_value, 0, strlen($vals)) .$str_html_fim . substr($str_value, strlen($vals));
                            }
                        }


                        elseif($_fld['opc'] == 'aw')
                        {
                            $args  = explode(" ", $vals);
                            foreach ($args as $cada_args) {
                                if (empty($cada_args)) {
                                    continue;
                                }
                                if(strcasecmp($cada_args, $str_value) == 0)
                                {
                                    $str_value = $str_html_ini. $str_value .$str_html_fim;
                                }
                                elseif(!empty($str_value_original) && $str_value_original != '&nbsp;' && strcasecmp($cada_args, $str_value_original) == 0)
                                {
                                    $str_value = $str_html_ini. $str_value .$str_html_fim;
                                }
                                else
                                {
                                    $keywords = preg_quote($cada_args, '/');
                                    $str_value = preg_replace('/'. $keywords .'/i', $str_html_ini . '$0' . $str_html_fim, $str_value);
                                }
                            }
                        }

                    }
                }
            }
        }
        elseif($filter_type == 'quicksearch')
        {
            if( isset($_SESSION['sc_session'][$this->Ini->sc_page]['grid_participantes_rsvp_1']['fast_search'][0]) &&
                (
                    (
                    $_SESSION['sc_session'][$this->Ini->sc_page]['grid_participantes_rsvp_1']['fast_search'][0] == 'SC_all_Cmp' &&
                    in_array($field, array('part_cpf', 'nome_pessoa', 'part_celeular_01', 'participante_id', 'part_ativo', 'part_sexo', 'part_crnm', 'part_tipo'))
                    ) ||
                    $_SESSION['sc_session'][$this->Ini->sc_page]['grid_participantes_rsvp_1']['fast_search'][0] == $field ||
                    strpos($_SESSION['sc_session'][$this->Ini->sc_page]['grid_participantes_rsvp_1']['fast_search'][0], $field . '_VLS_') !== false ||
                    strpos($_SESSION['sc_session'][$this->Ini->sc_page]['grid_participantes_rsvp_1']['fast_search'][0], '_VLS_' . $field) !== false
                )
            )
            {
                if($_SESSION['sc_session'][$this->Ini->sc_page]['grid_participantes_rsvp_1']['fast_search'][1] == 'qp')
                {
                    if(strcasecmp($_SESSION['sc_session'][$this->Ini->sc_page]['grid_participantes_rsvp_1']['fast_search'][2], $str_value) == 0)
                    {
                        $str_value = $str_html_ini. $str_value .$str_html_fim;
                    }
                    elseif(!empty($str_value_original) && $str_value_original != '&nbsp;' && strcasecmp($_SESSION['sc_session'][$this->Ini->sc_page]['grid_participantes_rsvp_1']['fast_search'][2], $str_value_original) == 0)
                    {
                        $str_value = $str_html_ini. $str_value .$str_html_fim;
                    }
                    else
                    {
                        $keywords = preg_quote($_SESSION['sc_session'][$this->Ini->sc_page]['grid_participantes_rsvp_1']['fast_search'][2], '/');
                        $str_value = preg_replace('/'. $keywords .'/i', $str_html_ini . '$0' . $str_html_fim, $str_value);
                    }
                }
/*--- mantis 24102 ---*/
                elseif($_SESSION['sc_session'][$this->Ini->sc_page]['grid_participantes_rsvp_1']['fast_search'][1] == 'aw')
                {
                    $args  = explode(" ", $_SESSION['sc_session'][$this->Ini->sc_page]['grid_participantes_rsvp_1']['fast_search'][2]);
                    foreach ($args as $cada_args) {
                        if (empty($cada_args)) {
                            continue;
                        }
                        if(strcasecmp($cada_args, $str_value) == 0)
                        {
                            $str_value = $str_html_ini. $str_value .$str_html_fim;
                        }
                        elseif(!empty($str_value_original) && $str_value_original != '&nbsp;' && strcasecmp($cada_args, $str_value_original) == 0)
                        {
                            $str_value = $str_html_ini. $str_value .$str_html_fim;
                        }
                        else
                        {
                            $keywords = preg_quote($cada_args, '/');
                            $str_value = preg_replace('/'. $keywords .'/i', $str_html_ini . '$0' . $str_html_fim, $str_value);
                        }
                    }
                }
/*------*/
                elseif($_SESSION['sc_session'][$this->Ini->sc_page]['grid_participantes_rsvp_1']['fast_search'][1] == 'eq')
                {
                    if(strcasecmp($_SESSION['sc_session'][$this->Ini->sc_page]['grid_participantes_rsvp_1']['fast_search'][2], $str_value) == 0)
                    {
                        $str_value = $str_html_ini. $str_value .$str_html_fim;
                    }
                    elseif(!empty($str_value_original) && $str_value_original != '&nbsp;' && strcasecmp($_SESSION['sc_session'][$this->Ini->sc_page]['grid_participantes_rsvp_1']['fast_search'][2], $str_value_original) == 0)
                    {
                        $str_value = $str_html_ini. $str_value .$str_html_fim;
                    }
                }
            }
        }
        return $str_value;
    }
