   function refresh_interativ_search()
   {
       $bol_refin_use_modal = true;
       if($_SESSION['scriptcase']['proc_mobile'])
       {
           $bol_refin_use_modal = false;
       }
       $array_fields = array();
       $array_fields[] = "part_contato_rsvp";
       $array_fields[] = "part_presenca";
       $array_fields[] = "part_solicit_especial";
       $array_fields[] = "part_aereo";
       $array_fields[] = "part_hospedagem";
       $array_fields[] = "part_transfer";
       $array_fields[] = "part_anotacoes";
       $array_fields[] = "part_confirm_viagem";
       $array_fields[] = "part_id_evento_publico";
       $array_fields[] = "part_id_evento_regional";
       if(is_array($array_fields) && !empty($array_fields))
       {
           $arr_new = [];
           foreach($array_fields as $key => $str_field)
           {
               if(isset($_SESSION['sc_session'][$this->Ini->sc_page]['grid_participantes_rsvp_1']['interativ_search'][$str_field]))
               {
                   unset($array_fields[ $key ]);
                   $arr_new[] = $str_field;
               }
           }
           $array_fields = array_merge($arr_new, $array_fields);
           $str_out = "";
           foreach($array_fields as $str_field)
           {
               $method = "interativ_search_" . $str_field;
               $str_out .= $this->$method($bol_refin_use_modal);
           }
           $this->Ini->Arr_result['setValue'][] = array('field' => 'id_div_interativ_search_fields', 'value' => NM_charset_to_utf8($str_out));
       }
   }
