   $nm_saida->saida("    function showNestedGridLinks(objectName, timeoutIndex, anchorObject)\r\n");
   $nm_saida->saida("    {\r\n");
   $nm_saida->saida("        if (\"undefined\" != typeof timeoutIndex) {\r\n");
   $nm_saida->saida("            clearTimeout(timeoutIndex);\r\n");
   $nm_saida->saida("        }\r\n");
   $nm_saida->saida("        let thisObject = document.getElementById(objectName);\r\n");
   $nm_saida->saida("        thisObject.style.display = '';\r\n");
   $nm_saida->saida("        if (\"undefined\" != typeof anchorObject && \"null\" != typeof anchorObject) {\r\n");
   $nm_saida->saida("            positionNestedGridLinks(anchorObject, thisObject);\r\n");
   $nm_saida->saida("        }\r\n");
   $nm_saida->saida("    }\r\n");
   $nm_saida->saida("    function hideNestedGridLinks(objectName, linkType)\r\n");
   $nm_saida->saida("    {\r\n");
   $nm_saida->saida("        let thisObject = document.getElementById(objectName);\r\n");
   $nm_saida->saida("        if ('a' == linkType) {\r\n");
   $nm_saida->saida("            timeoutIndex = setTimeout(function() { thisObject.style.display = 'none'; }, 200);\r\n");
   $nm_saida->saida("            return timeoutIndex;\r\n");
   $nm_saida->saida("        } else {\r\n");
   $nm_saida->saida("            thisObject.style.display = 'none';\r\n");
   $nm_saida->saida("            return null;\r\n");
   $nm_saida->saida("        }\r\n");
   $nm_saida->saida("    }\r\n");
   $nm_saida->saida("    function positionNestedGridLinks(anchorObject, menuElement) {\r\n");
